#!/usr/bin/env python3
import os
import requests
from flask import Flask, request, jsonify

NETWORK = os.environ.get("SOLANA_NETWORK", "devnet").lower()
RPC_URLS = {
    "devnet": "https://api.devnet.solana.com",
    "testnet": "https://api.testnet.solana.com",
    "mainnet-beta": "https://api.mainnet-beta.solana.com",
}
if NETWORK not in RPC_URLS:
    NETWORK = "devnet"
RPC_URL = RPC_URLS[NETWORK]

app = Flask(__name__)

def rpc(method, params=None, timeout=60):
    payload = {"jsonrpc": "2.0", "id": 1, "method": method,
               "params": params if params is not None else []}
    try:
        resp = requests.post(RPC_URL, json=payload, timeout=timeout)
        resp.raise_for_status()
    except requests.RequestException as e:
        raise RuntimeError("RPC request failed: %s" % str(e))
    data = resp.json()
    if data.get("error"):
        err = data["error"]
        msg = err.get("message") if isinstance(err, dict) else str(err)
        raise RuntimeError(msg)
    return data.get("result")

@app.route("/status")
def status():
    try:
        try:
            health = rpc("getHealth")
            online = (health == "ok")
        except Exception:
            online = False
        status_val = "online" if online else "offline"
        current_slot = node_count = version = None
        if online:
            try:
                current_slot = rpc("getSlot")
            except Exception:
                current_slot = None
            try:
                nodes = rpc("getClusterNodes")
                node_count = len(nodes) if isinstance(nodes, list) else None
            except Exception:
                node_count = None
            try:
                ver = rpc("getVersion")
                version = ver.get("solana-core") if isinstance(ver, dict) else None
            except Exception:
                version = None
        return jsonify({
            "status": status_val,
            "network": NETWORK,
            "current_slot": current_slot,
            "node_count": node_count,
            "version": version,
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/block/<int:slot_number>")
def block(slot_number):
    try:
        params = [slot_number, {"encoding": "json", "transactionDetails": "none", "rewards": False}]
        b = rpc("getBlock", params)
        if b is None:
            return jsonify({"error": "block %d not found" % slot_number}), 404
        return jsonify({
            "blockhash": b.get("blockhash"),
            "parent_slot": b.get("parentSlot"),
            "previous_blockhash": b.get("previousBlockhash"),
            "block_height": b.get("blockHeight"),
            "block_time": b.get("blockTime"),
        })
    except Exception as e:
        msg = str(e)
        if any(k in msg.lower() for k in ("skipped", "not found", "missing")):
            return jsonify({"error": msg}), 404
        return jsonify({"error": msg}), 500

@app.route("/transaction/<path:signature>")
def transaction(signature):
    try:
        params = [signature, {"encoding": "jsonParsed", "maxSupportedTransactionVersion": 0}]
        tx = rpc("getTransaction", params)
        if tx is None:
            return jsonify({"error": "transaction not found"}), 404
        meta = tx.get("meta") or {}
        msg = (tx.get("transaction") or {}).get("message", {})
        account_keys = msg.get("accountKeys", []) or []
        def key_at(i):
            if i < 0 or i >= len(account_keys):
                return None
            k = account_keys[i]
            return k.get("pubkey") if isinstance(k, dict) else k
        idx_to_pubkey = {i: key_at(i) for i in range(len(account_keys))}
        def balances(lst):
            m = {}
            for bt in (lst or []):
                ai = bt.get("accountIndex")
                pk = idx_to_pubkey.get(ai)
                mint = bt.get("mint")
                amt = (bt.get("uiTokenAmount") or {}).get("amount")
                amt = int(amt) if amt is not None else 0
                m[pk] = (mint, amt)
            return m
        pre = balances(meta.get("preTokenBalances"))
        post = balances(meta.get("postTokenBalances"))
        token_transfers = []
        for pk in set(pre.keys()) | set(post.keys()):
            pa = pre.get(pk, (None, 0))[1]
            po = post.get(pk, (None, 0))[1]
            if pa != po:
                mint = (post.get(pk) or pre.get(pk))[0]
                token_transfers.append({
                    "account": pk,
                    "mint": mint,
                    "amount": abs(po - pa),
                })
        sigs = ((tx.get("transaction") or {}).get("signatures") or [])
        sig = sigs[0] if sigs else signature
        return jsonify({
            "signature": sig,
            "slot": tx.get("slot"),
            "block_time": tx.get("blockTime"),
            "success": meta.get("err") is None,
            "fee": meta.get("fee"),
            "token_transfers": token_transfers,
        })
    except Exception as e:
        msg = str(e)
        if any(k in msg.lower() for k in ("not found", "missing", "skipped")):
            return jsonify({"error": msg}), 404
        return jsonify({"error": msg}), 500

@app.route("/account/<path:address>")
def account(address):
    try:
        params = [address, {"encoding": "base64", "commitment": "confirmed"}]
