                    "lamports": acc.get("lamports"),
                    "owner": acc.get("owner"),
                    "rent_epoch": acc.get("rentEpoch"),
                },
            })
        return jsonify({
            "program_id": program_id,
            "total_accounts": total,
            "limit": limit,
            "offset": offset,
            "accounts": out,
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
